class AgentActivity:

    def __init__(self, root: Path, registry: Registration):
        self.registry = registry
        self._wire_lock_path = root / 'wire'
        self.activity = ActivityLog(root / 'activity.jsonl')
        self.runtime_info = RuntimeInfoStore(root / RuntimeInfoStore.filename)

    def set_activity(self, thread: str, state: ActivityState, detail: str='') -> None:
        """Declare a thread's current activity (thinking/working/idle)."""
        if state.retires_thread:
            raise RelationViolationError('Only permanent thread deletion retires its activity.')
        with _store_lock(self._wire_lock_path, shared=True):
            self._emit_activity(Activity.create(thread, state, detail))

    def activity_of(self, thread: str, *, snapshot: RegistrySnapshot | None=None) -> ObservedActivity:
        snapshot = snapshot or self.registry.snapshot()
        owner = snapshot.owner_identity(thread)
        participant = snapshot.threads[owner.incarnation.name]
        return self._observed(participant, owner, self.activity.current(participant.name, active=participant.executing))

    def _observed(self, participant: Thread, owner: OwnerIdentity, event: Activity) -> ObservedActivity:
        activity = ObservedActivity.acquire(event, owner)
        return participant.execution.project_activity(participant, activity)

    def all_activity(self, threads: Iterable[Thread], *, snapshot: RegistrySnapshot) -> Mapping[str, ObservedActivity]:
        requested = {thread.name: thread for thread in threads}
        if not requested:
            return {}
        events = self.activity.current_for(requested, active=frozenset((name for name, thread in requested.items() if thread.executing)))
        return {name: self._observed(thread, snapshot.owner_identity(name), events[name]) for name, thread in requested.items()}

    def observe_recipients(self, recipients: Iterable[tuple[CommittedDelivery, FrozenRecipient]], *, snapshot: RegistrySnapshot) -> Mapping[str, RecipientActivity]:
        """Acquire one bounded window's recipients from the original sends."""
        observations: dict[str, RecipientActivity] = {}
        for original, recipient in recipients:
            lookup = recipient.recipient_lookup
            if lookup in observations:
                continue
            selected = snapshot.recipient(recipient, original)
            observations[lookup] = selected.activity(self, snapshot)
        return observations

    def _emit_activity(self, activity: Activity) -> None:
        snapshot = self.registry.snapshot()
        owner = snapshot.owner_identity(activity.thread)
        activity = replace(activity, thread=owner.incarnation.name)
        self.activity.update(activity.thread, lambda current: replace(activity, diagnostic=ObservedActivity.acquire(current, owner).readiness.source_diagnostic()))

