class AssignmentStore:

    def __init__(self, session: CoordinationSession) -> None:
        self.session = session

    def get(self, assignment_id: str) -> WakeAssignment:
        row = WakeAssignment.one(self.session._connection, assignment_id=assignment_id)
        if row is None:
            raise IdentityConflict('unknown claim')
        return row

    def accept(self, assignment: WakeAssignment) -> Applied[WakeAssignment] | AlreadyApplied[WakeAssignment]:
        assignment.require_initial_decision()
        with self.session.transaction() as db:
            rows = WakeAssignment.read(db.execute('SELECT * FROM wake_claims WHERE assignment_id=? OR (recipient_lookup=? AND wire_seq=?) LIMIT 1', (assignment.assignment_id, assignment.recipient_lookup, assignment.wire_seq)))
            row = next(iter(rows), None)
            if row is not None:
                current = row
                current.require_same_acceptance(assignment)
                return AlreadyApplied(current)
            assignment.insert(db)
            return Applied(assignment)

    def recoverable_unbound_deliveries(self, recipient_lookup: str, sources: frozenset[MessageReference]) -> tuple[WakeAssignment, ...]:
        """Paused following deliveries with neither send binding nor native source."""
        from agent_comms.native_runtime_input import NativeRuntimeInput
        if not sources:
            return ()
        with self.session.read():
            db = self.session._connection
            deferred = WakeAssignment.read(db.execute(f'SELECT * FROM wake_claims claims WHERE recipient_lookup=? AND disposition={sql_literal(DeferredAssignment)} AND execution_id IS NULL AND NOT EXISTS (SELECT 1 FROM ({NativeRuntimeInput.source_membership_sql()}) sources WHERE sources.assignment_id=claims.assignment_id)', (recipient_lookup,)))
            return tuple((current for current in deferred if current.source in sources and current.lifecycle == DeferredAssignment.build(current.lifecycle.mode, None, None)))

    def restore_unbound_delivery(self, captured: WakeAssignment) -> WakeAssignment:
        """Return one proved-not-sent following delivery to its declared initial state."""
        current = self.get(captured.assignment_id)
        if current != captured:
            raise StaleRevision('unbound delivery assignment changed')
        return self.transition_preengagement(current.assignment_id, current.lifecycle.mode.initial_state, expected_revision=current.revision).value

    def transition_preengagement(self, assignment_id: str, disposition: type[AssignmentState], *, expected_revision: int) -> Applied[WakeAssignment]:
        with self.session.transaction() as db:
            current = self.get(assignment_id)
            if current.revision != expected_revision:
                raise StaleRevision('claim revision changed')
            lifecycle = current.lifecycle.preengagement(disposition)
            after = replace(current, updated_at_ms=self.session.now(current.updated_at_ms), revision=current.revision + 1, lifecycle=lifecycle)
            WakeAssignment.update(db, where='assignment_id=? AND revision=?', parameters=(assignment_id, expected_revision), lifecycle=after.lifecycle, updated_at_ms=after.updated_at_ms, revision=after.revision)
            return Applied(after)

def restore_unbound_delivery(self, captured: WakeAssignment) -> WakeAssignment:
    """Return one proved-not-sent following delivery to its declared initial state."""
    current = self.get(captured.assignment_id)
    if current != captured:
        raise StaleRevision('unbound delivery assignment changed')
    return self.transition_preengagement(current.assignment_id, current.lifecycle.mode.initial_state, expected_revision=current.revision).value

@dataclass(frozen=True, slots=True)
class CommittedDelivery(MessageWireRecord):
    """Bus-reader delivery, for both an original and a keyed response."""
    wire_root_id: str
    message: Message
    audience: FrozenAudience
    decisions: tuple[WakeDecision, ...]
    decisions_digest: str
    control: str
    resolver_version: str
    policy_version: str
    manifest_codec: str = INITIAL_CODEC
    receipt: KeyedResponseReceipt | None = None

    def assignment_decisions(self) -> Iterator[tuple[FrozenRecipient, WakeDecision, AssignmentState]]:
        """Selected frozen members with their declared initial lifecycle, never observers."""
        from .coordination_errors import IntegrityViolationError
        for recipient, decision in zip(self.audience.recipients, self.decisions, strict=True):
            if recipient.recipient_lookup != decision.recipient:
                raise IntegrityViolationError('bus decision does not match frozen N')
            if not decision.audience.observer:
                yield (recipient, decision, decision.wake_mode.initial_state())

    def direct_for(self, recipient_lookup: str) -> bool:
        """Direct reply semantics and its original addressed incarnation agree."""
        policy = self.message.response_policy
        return policy.starts_turn and policy.separate_turn and self.audience.includes_lookup(recipient_lookup)

    def compaction_messages_for(self, recipient_lookup):
        addressed = self.audience.includes_lookup(recipient_lookup)
        authored = self.audience.sender_lookup == recipient_lookup and self.message.retains_authored_task
        return self.messages() if addressed or authored else ()

    @classmethod
    def from_wire(cls, record: Mapping[str, object], wire_root_id: str) -> CommittedDelivery:
        from .messages import Message
        return cls.attest(Message.from_committed_wire(record), record, wire_root_id)

    @classmethod
    def attest(cls, message: Message, record: Mapping[str, object], wire_root_id: str) -> CommittedDelivery:
        """Validate the declared private policy against the already decoded public message."""
        from agent_comms.coordination_contracts import POLICY_VERSION, RESOLVER_VERSION
        from .audience_manifest import freeze_audience
        from .delivery_policy import DeliveryPolicy
        from .field_codec import FieldCodec
        if set((key for key in record if key.startswith(_PRIVATE_WIRE_PREFIX))) != {PRIVATE_WIRE_FIELD}:
            raise ValueError('Unknown private bus namespace.')
        private = record[PRIVATE_WIRE_FIELD]
        policy = FieldCodec.decode(DeliveryPolicy, private)
        if _canonical(private) != _canonical(FieldCodec.encode(policy)):
            raise ValueError('Private publication is not canonical.')
        raw = policy.initial
        if raw.wire_root_id != wire_root_id:
            raise ValueError('Delivery belongs to another wire root.')
        if raw.manifest_codec != INITIAL_CODEC:
            raise ValueError('Unsupported delivery manifest codec.')
        if raw.resolver_version != RESOLVER_VERSION or raw.policy_version != POLICY_VERSION:
            raise ValueError('Unsupported delivery decision versions.')
        if not raw.control.supports_initial:
            raise ValueError('Unsupported delivery control issuer.')
        audience = raw.audience
        if _HEX64.fullmatch(audience.source_revision) is None:
            raise ValueError('Delivery source revision is invalid.')
        lookups = (audience.sender_lookup, *(r.recipient_lookup for r in audience.recipients))
        if any((_HEX32.fullmatch(lookup) is None for lookup in lookups)):
            raise ValueError('Delivery creator or recipient lookup is invalid.')
        candidate = freeze_audience(message, audience.recipients, audience.source_revision, sender_lookup=audience.sender_lookup, sender_name=audience.sender_name)
        if audience != candidate:
            raise ValueError('Delivery audience differs fr

def initial_sideband(wire_root_id: str, message: Message, audience: FrozenAudience, decisions: tuple[WakeDecision, ...], *, control: str) -> DeliveryManifest:
    """Serialize once at the committed-bus boundary; no independent sidecar."""
    from agent_comms.coordination_contracts import POLICY_VERSION, RESOLVER_VERSION
    if len(decisions) != len(audience.recipients):
        raise ValueError('Every frozen recipient requires a selected or no-wake decision.')
    from .delivery_policy import DeliveryManifest
    from .wake import ControlClassification
    rows = decisions_wire(decisions)
    return DeliveryManifest(wire_root_id, INITIAL_CODEC, RESOLVER_VERSION, POLICY_VERSION, ControlClassification(control), audience, rows, decisions_digest(rows))

