@classmethod
def attest(cls, message: Message, record: Mapping[str, object], wire_root_id: str) -> CommittedDelivery:
    """Validate the declared private policy against the already decoded public message."""
    from agent_comms.coordination_contracts import POLICY_VERSION, RESOLVER_VERSION
    from .audience_manifest import freeze_audience
    from .delivery_policy import DeliveryPolicy
    from .field_codec import FieldCodec
    if set((key for key in record if key.startswith(_PRIVATE_WIRE_PREFIX))) != {PRIVATE_WIRE_FIELD}:
        raise ValueError('Unknown private bus namespace.')
    private = record[PRIVATE_WIRE_FIELD]
    policy = FieldCodec.decode(DeliveryPolicy, private)
    if _canonical(private) != _canonical(FieldCodec.encode(policy)):
        raise ValueError('Private publication is not canonical.')
    raw = policy.initial
    if raw.wire_root_id != wire_root_id:
        raise ValueError('Delivery belongs to another wire root.')
    if raw.manifest_codec != INITIAL_CODEC:
        raise ValueError('Unsupported delivery manifest codec.')
    if raw.resolver_version != RESOLVER_VERSION or raw.policy_version != POLICY_VERSION:
        raise ValueError('Unsupported delivery decision versions.')
    if not raw.control.supports_initial:
        raise ValueError('Unsupported delivery control issuer.')
    audience = raw.audience
    if _HEX64.fullmatch(audience.source_revision) is None:
        raise ValueError('Delivery source revision is invalid.')
    lookups = (audience.sender_lookup, *(r.recipient_lookup for r in audience.recipients))
    if any((_HEX32.fullmatch(lookup) is None for lookup in lookups)):
        raise ValueError('Delivery creator or recipient lookup is invalid.')
    candidate = freeze_audience(message, audience.recipients, audience.source_revision, sender_lookup=audience.sender_lookup, sender_name=audience.sender_name)
    if audience != candidate:
        raise ValueError('Delivery audience differs from committed public envelope.')
    decisions = policy.resolve(message, candidate, raw.control)
    rows = decisions_wire(decisions)
    if raw.decisions != rows or raw.decisions_digest != decisions_digest(rows):
        raise ValueError('Delivery decisions do not match the full committed N.')
    receipt = policy.require_receipt(wire_root_id, message)
    return cls(wire_root_id, message, candidate, decisions, raw.decisions_digest, raw.control.value, RESOLVER_VERSION, POLICY_VERSION, receipt=receipt)

def _verify_selected_wake_state(initial: CommittedDelivery, owner: Thread, generation: int, store: Coordination, admission: WakeAdmission) -> None:
    """Check an already locked bus/owner snapshot against one SQL state."""
    registry_owner = RegistryOwner(thread=owner, admission_generation=generation)
    try:
        turn = registry_owner.require_active_turn()
    except StaleFence as error:
        raise IdentityConflict('Wake source or owner turn does not match') from error
    if initial.message.reference != admission.source:
        raise IdentityConflict('Wake source message changed')
    if owner.incarnation.lookup != admission.recipient_lookup:
        raise IdentityConflict('Wake recipient incarnation changed')
    if generation != admission.owner_admission_generation or turn.id != admission.turn_id:
        raise IdentityConflict('Wake source or owner turn does not match')
    with store.session.read():
        assert_cohort_schema(store.session._connection)
        receipt = _receipt_matches(store.session._connection, initial)
        if not any((assignment.assignment_id == admission.wake_assignment_id for assignment in receipt.assignments)):
            raise IdentityConflict('Wake claim is not in the sealed selected cohort')
        assignment = store.assignments.get(admission.wake_assignment_id)
        participant = store.participants.get(admission.recipient_lookup)
        snapshot = store.snapshots.get(admission.execution_id)
        if assignment.require_engaged_binding() != admission.binding:
            raise IdentityConflict('Wake assignment binding changed')
        expected_owner = OwnerGenerations(owner_lookup=admission.recipient_lookup, owner_thread=owner.name, generation=admission.participant_generation)
        if not participant.committed or participant.owner_identity != expected_owner:
            raise IdentityConflict('Wake participant generation changed')
        try:
            attempt = snapshot.require_current_attempt()
        except StaleFence as error:
            raise IdentityConflict('Wake execution is not the current selected attempt') from error
        if attempt.owner_identity != expected_owner or attempt.attempt_ordinal != admission.attempt_ordinal:
            raise IdentityConflict('Wake selected attempt owner changed')
        if snapshot.execution.owner_thread != owner.name:
            raise IdentityConflict('Wake execution owner changed')
        if not attempt.lifecycle.tool_admission_open:
            raise IdentityConflict('Wake execution is not the current selected attempt')
        if assignment not in snapshot.assignments or assignment.recipient != owner.name:
            raise IdentityConflict("Wake assignment is not a member of this owner's execution")

def _committed_source(bus_lock: StoreLock, admission: WakeAdmission, absent: str) -> CommittedDelivery:
    """The message a selected turn answers, read through the held bus lock's checkpoint."""
    try:
        return bus_lock.certified_read().delivery(admission.source_seq)
    except RelationViolationError as error:
        raise IdentityConflict(absent) from error

