def _receipt_matches(db: sqlite3.Connection, initial: CommittedDelivery) -> AcceptedCohort:
    message = initial.message
    audience = initial.audience
    row = ClaimBatchReceipts.one(db, wire_root_id=initial.wire_root_id, wire_seq=message.seq)
    if row is None or not row.sealed:
        raise IdentityConflict('cohort receipt is absent or unsealed')
    expected = _expected_assignments(initial, row.accepted_at_ms)
    expected_count = len(expected)
    if any((getattr(row, field) != expected for field, expected in (('message_id', message.message_id), ('exact_target', message.target), ('envelope_digest', audience.wire_envelope_digest), ('audience_digest', audience.digest), ('decisions_digest', initial.decisions_digest), ('member_count', len(audience.recipients)), ('claim_count', expected_count), ('manifest_codec', initial.manifest_codec), ('resolver_version', initial.resolver_version), ('policy_version', initial.policy_version)))):
        raise IdentityConflict('sealed cohort receipt conflicts with committed bus')
    members = ClaimBatchMembers.select(db, where='wire_root_id=? AND wire_seq=?', parameters=(initial.wire_root_id, message.seq), order_by=('ordinal',))
    if members != [ClaimBatchMembers(wire_root_id=initial.wire_root_id, wire_seq=message.seq, ordinal=ordinal, claim_id=assignment.assignment_id, recipient_lookup=assignment.recipient_lookup) for ordinal, assignment in enumerate(expected)]:
        raise IdentityConflict('sealed K claim members conflict with committed bus')
    deliveries = CohortDeliveryReceipts.select(db, where='wire_root_id=? AND wire_seq=?', parameters=(initial.wire_root_id, message.seq), order_by=('ordinal',))
    selected = {assignment.recipient_lookup: assignment.assignment_id for assignment in expected}
    if deliveries != [CohortDeliveryReceipts(wire_root_id=initial.wire_root_id, wire_seq=message.seq, ordinal=ordinal, recipient_lookup=recipient.recipient_lookup, canonical_thread=recipient.canonical_thread, kind='selected' if recipient.recipient_lookup in selected else 'unmentioned_observer', claim_id=selected.get(recipient.recipient_lookup)) for ordinal, recipient in enumerate(audience.recipients)]:
        raise IdentityConflict('sealed N delivery receipts conflict with committed bus')
    current: list[WakeAssignment] = []
    for accepted in expected:
        db_row = WakeAssignment.one(db, assignment_id=accepted.assignment_id)
        if db_row is None:
            raise IdentityConflict('sealed cohort claim is missing')
        actual = db_row
        if not _immutable_assignment_matches(actual, accepted):
            raise IdentityConflict('sealed cohort claim immutable facts conflict')
        current.append(actual)
    if any((WakeAssignment.one(db, recipient_lookup=recipient.recipient_lookup, wire_seq=message.seq) for recipient in audience.recipients if recipient.recipient_lookup not in selected)):
        raise IdentityConflict('no-wake observer has a conflicting unbound claim')
    return AcceptedCohort(initial.wire_root_id, message.seq, message.message_id, len(audience.recipients), len(expected), row.accepted_at_ms, tuple(current))

def accept_delivery_cohort(bus: MessageBus, wire_root_id: str, wire_seq: int, store: Coordination) -> Applied[AcceptedCohort] | AlreadyApplied[AcceptedCohort]:
    """Bus-read first, then one SQLite transaction for every N/K fact.

    Participants are separately durable identities; this cannot manufacture a
    participant owner or commit one based merely on a bus message. If the
    coordinator has not registered each frozen stable lookup, no N is accepted.
    """
    if type(bus) is not MessageBus or type(store) is not Coordination:
        raise TypeError('cohort acceptance requires the actual bus and coordinator stores')
    with bus.log.certified_read() as source, store.session.transaction() as db:
        marker = source.marker
        if marker.root_id != wire_root_id:
            raise IdentityConflict('cohort admission wire root changed')
        if wire_seq <= marker.admission_after_seq:
            raise IdentityConflict('historical source precedes the current admission floor')
        initial = source.delivery(wire_seq)
        assert_cohort_schema(db)
        receipt = ClaimBatchReceipts.one(db, wire_root_id=wire_root_id, wire_seq=wire_seq)
        if receipt is not None:
            return AlreadyApplied(_receipt_matches(db, initial))
        if WakeAssignment.select(db, where='wire_seq=?', parameters=(wire_seq,)):
            raise IdentityConflict('singleton claim cannot be adopted by a cohort')
        if ClaimBatchReceipts.select(db, where='wire_seq=?', parameters=(wire_seq,)):
            raise IdentityConflict('wire sequence already belongs to another cohort root')
        for recipient in initial.audience.recipients:
            if Participants.one(db, participant_lookup=recipient.recipient_lookup) is None:
                raise IdentityConflict('frozen recipient has no durable participant identity')
        accepted_at = store.session.now()
        expected = _expected_assignments(initial, accepted_at)
        ClaimBatchReceipts(wire_root_id=wire_root_id, wire_seq=wire_seq, message_id=initial.message.message_id, exact_target=initial.message.target, envelope_digest=initial.audience.wire_envelope_digest, audience_digest=initial.audience.digest, decisions_digest=initial.decisions_digest, member_count=len(initial.audience.recipients), claim_count=len(expected), manifest_codec=initial.manifest_codec, resolver_version=initial.resolver_version, policy_version=initial.policy_version, accepted_at_ms=accepted_at).insert(db)
        for ordinal, assignment in enumerate(expected):
            assignment.insert(db)
            ClaimBatchMembers(wire_root_id=wire_root_id, wire_seq=wire_seq, ordinal=ordinal, claim_id=assignment.assignment_id, recipient_lookup=assignment.recipient_lookup).insert(db)
        selected = {assignment.recipient_lookup: assignment.assignment_id for assignment in expected}
        for ordinal, recipient in enumerate(initial.audience.recipients):
            assignment_id = selected.get(recipient.recipient_lookup)
            CohortDeliveryReceipts(wire_root_id=wire_root_id, wire_seq=wire_seq, ordinal=ordinal, recipient_lookup=recipient.recipient_lookup, canonical_thread=recipient.canonical_thread, kind='selected' if assignment_id is not None else 'unmentioned_observer', claim_id=assignment_id).insert(db)
        _record_optional_owner_generations(db, expected, wire_root_id, wire_seq)
        ClaimBatchReceipts.update(db, where='wire_root_id=? AND wire_seq=?', parameters=(wire_root_id, wire_seq), sealed=True)
        return Applied(_receipt_matches(db, initial))

def _require_cohort_assignments(store: Coordination, bus: MessageBus, snapshot: RecoverySnapshot, wire_root_id: str, *, terminal: bool=False) -> None:
    """Bind selected SQL facts to the ORIGINAL bus origin and exact reply route.

    A DM reply targets the original sender, not the DM's incoming target.
    Caller already holds the bus file lock before the SQL transaction.
    """
    db = store.session._connection
    _assert_response_schema(db)
    assert_cohort_schema(db)
    snapshot.require_wire_responses()
    metadata = bus.log._private_marker_unlocked()
    if metadata.root_id != wire_root_id:
        raise IdentityConflict('cohort bus root changed')
    originals = {initial.message.seq: initial for initial in bus.log.delivery_cohorts_unlocked(wire_root_id, tuple((assignment.wire_seq for assignment in snapshot.assignments)))}
    for assignment in snapshot.assignments:
        initial = originals.get(assignment.wire_seq)
        receipts = SelectedResponseRoute.read(db.execute("SELECT r.message_id,r.exact_target,r.envelope_digest,r.audience_digest,r.decisions_digest,r.resolver_version,r.policy_version,m.recipient_lookup,d.canonical_thread FROM claim_batch_members m JOIN claim_batch_receipts r ON r.wire_root_id=m.wire_root_id AND r.wire_seq=m.wire_seq JOIN cohort_delivery_receipts d ON d.wire_root_id=m.wire_root_id AND d.wire_seq=m.wire_seq AND d.claim_id=m.claim_id AND d.kind='selected' WHERE m.claim_id=? AND m.wire_root_id=? AND r.sealed=1", (assignment.assignment_id, wire_root_id)))
        if initial is None or len(receipts) != 1:
            raise IdentityConflict('response claim lacks original bus/cohort authority')
        selected = {recipient.recipient_lookup for recipient, _decision, _lifecycle in initial.assignment_decisions()}
        if initial.wire_root_id != wire_root_id or assignment.source != initial.message.reference:
            raise IdentityConflict('response claim conflicts with original bus source')
        receipts[0].require_source(initial, assignment)
        if assignment.recipient_lookup not in selected:
            raise IdentityConflict('response recipient was not selected by the original source')
        engagement = assignment.lifecycle.require_completion() if terminal else assignment.lifecycle.require_engagement()
        if engagement.exact_target != initial.message.exact_reply_target:
            raise IdentityConflict('response claim conflicts with original selected bus route')

