class GoalWait(ABC):
    """A resolved dependency state; only RecordedGoalWait is persisted."""

    @abstractmethod
    def allows_routed_input(self) -> bool:
        ...

    def matches_id(self, wait_id: str) -> bool:
        return False

    def owner_matches(self, created_at: float) -> bool:
        return False

    def matches(self, original: CommittedDelivery, owner: RecordedThreadIncarnation) -> bool:
        return False

    def consume_dependency(self, comms, canonical: str) -> bool:
        return True

    def consume_reply(self, waits: GoalWaits, goal_id: str) -> bool:
        return False

    def project(self, goal: Goal, snapshot: RegistrySnapshot) -> GoalExecution:
        return GoalExecution(GoalExecutionState.for_domain_state(goal.state), goal.id, block_reason=goal.state.reason)

@dataclass(frozen=True, slots=True)
class RecordedGoalWait(GoalWait):
    goal_id: str
    wait_id: str
    revision: int
    after_seq: int
    targets: tuple[GoalWaitTarget, ...]
    owner_created_at: float
    target_turn_generations: tuple[int | None, ...]
    report_turn_id: str | None
    report_turn_generation: int | None

    def __post_init__(self) -> None:
        if type(self.owner_created_at) not in (int, float) or not math.isfinite(self.owner_created_at) or self.owner_created_at <= 0 or (len(self.target_turn_generations) != len(self.targets)) or any((generation is not None and (type(generation) is not int or generation <= 0) for generation in self.target_turn_generations)):
            raise ValueError('A wait requires its owner incarnation and aligned target turns.')
        if (self.report_turn_id is None) != (self.report_turn_generation is None) or (self.report_turn_id is not None and (not self.report_turn_id or type(self.report_turn_generation) is not int or self.report_turn_generation <= 0)):
            raise ValueError('A reporting turn requires both its ID and generation.')

    def allows_routed_input(self) -> bool:
        return False

    def matches_id(self, wait_id: str) -> bool:
        return self.wait_id == wait_id

    def owner_matches(self, created_at: float) -> bool:
        return self.owner_created_at == created_at

    def consume_dependency(self, comms, canonical: str) -> bool:
        return comms.goals.consume_goal_wait(canonical, self.wait_id)

    def consume_reply(self, waits: GoalWaits, goal_id: str) -> bool:
        return waits.clear(goal_id, wait_id=self.wait_id)

    def project(self, goal: Goal, snapshot: RegistrySnapshot) -> GoalExecution:
        targets = tuple((GoalWaitTarget(target.incarnation.renamed(snapshot.canonical_name(target.incarnation.name))) for target in self.targets))
        inactive = tuple((target for target in targets if not GoalWaits.target_has_active_turn(target, snapshot)))
        return GoalExecution(GoalExecutionState.STANDBY, goal.id, targets, inactive)

    def current_for(self, goal: Goal, owner_created_at: float) -> bool:
        """A retained wait can survive edits, but not replacement of its owner.

        Callers select the row by goal ID before asking this question. A newer
        goal revision preserves the declared wait; a future wait revision does
        not belong to the observed goal snapshot.
        """
        return self.owner_created_at == owner_created_at and goal.accepts_observation(self.goal_id, self.revision)

    def matches(self, original: CommittedDelivery, owner: RecordedThreadIncarnation) -> bool:
        """Join original sender and the actual addressed owner through its source."""
        if not self.owner_matches(owner.created_at):
            return False
        return original.message.seq > self.after_seq and original.direct_for(owner.lookup) and any((target.sent(original) for target in self.targets))

    def has_reply(self, bus: WireLog, owner: RecordedThreadIncarnation) -> bool:
        if not self.owner_matches(owner.created_at):
            return False
        return any((self.matches(original, owner) for original in bus.addressed_sources(owner.lookup, self.after_seq)))

def matches(self, original: CommittedDelivery, owner: RecordedThreadIncarnation) -> bool:
    """Join original sender and the actual addressed owner through its source."""
    if not self.owner_matches(owner.created_at):
        return False
    return original.message.seq > self.after_seq and original.direct_for(owner.lookup) and any((target.sent(original) for target in self.targets))

class NativeSourceCursor:
    """Own current cursor observation and monotonic publication for one private bus."""

    def __init__(self, bus: MessageBus, store: Coordination, *, wire_root_id: str) -> None:
        if type(bus) is not MessageBus or type(store) is not Coordination:
            raise ValueError('current native cursor needs actual private stores')
        self.bus, self.store, self.wire_root_id = (bus, store, wire_root_id)

