def _publish(db: sqlite3.Connection, owner: CursorOwner, prior: CurrentNativeCursor | None, coverage: ProvenSourceCoverage, proof: HistoricalNativeInput | None) -> CurrentNativeCursor:
    cursor = CurrentNativeCursor(wire_root_id=owner.wire_root_id, recipient_lookup=owner.lookup, owner_thread=owner.thread.name, owner_generation=owner.generation, owner_admission_generation=owner.admission_generation, covered_seq=coverage.covered_seq, injected_seq=coverage.injected_source_seqs[-1] if coverage.injected_source_seqs else 0, input_id=proof.input_id if proof else None, stage=type(proof.execution) if proof else None, session_id=proof.context.session_id if proof else None, request_generation=proof.context.request_generation if proof else None)
    if prior is None:
        cursor.insert(db)
    elif cursor.covered_seq > prior.covered_seq or cursor.injected_seq > prior.injected_seq:
        updated = CurrentNativeCursor.update(db, where='wire_root_id=? AND recipient_lookup=? AND owner_generation=? AND owner_admission_generation=? AND covered_seq=? AND injected_seq=?', parameters=(owner.wire_root_id, owner.lookup, owner.generation, owner.admission_generation, prior.covered_seq, prior.injected_seq), covered_seq=cursor.covered_seq, injected_seq=cursor.injected_seq, input_id=cursor.input_id, stage=cursor.stage, session_id=cursor.session_id, request_generation=cursor.request_generation)
        if updated.rowcount != 1:
            raise StaleFence('current cursor monotonic update lost its fence')
    else:
        return prior
    return cursor

