def _verify_schema_and_owner(self, db: sqlite3.Connection, initial: CommittedDelivery, assignment: WakeAssignment, owner: Thread) -> None:
    versions = SQLiteUserVersion.read(db.execute('PRAGMA user_version'))
    meta = _CoordinatorVersions.read(db.execute('SELECT schema_version,snapshot_version FROM schema_meta WHERE singleton=1'))
    if versions != [SQLiteUserVersion(COORDINATION_SCHEMA_VERSION)] or meta != [_CoordinatorVersions(COORDINATION_SCHEMA_VERSION, COORDINATION_SNAPSHOT_VERSION)]:
        raise ProjectionUnavailableError('coordinator schema changed')
    assert_cohort_schema(db)
    assert_optional_awareness_schema(db)
    cohort_versions = _CohortVersion.read(db.execute('SELECT version FROM cohort_schema_meta WHERE singleton=1'))
    if cohort_versions != [_CohortVersion(COHORT_SCHEMA_VERSION)]:
        raise ProjectionUnavailableError('cohort schema changed')
    people = _ParticipantOwner.read(db.execute('SELECT p.committed,g.owner_thread,g.generation FROM participants p JOIN owner_generations g ON g.owner_lookup=p.participant_lookup WHERE p.participant_lookup=?', (assignment.recipient_lookup,)))
    if people != [_ParticipantOwner(self.expected_participant_generation, True, owner.name)]:
        raise ProjectionUnavailableError('selected participant owner changed')
    receipt = _receipt_matches(db, initial)
    if not any((current == assignment for current in receipt.assignments)):
        raise ProjectionUnavailableError('current selected claim lost its sealed receipt')

