@classmethod
def project_delivery_window(cls, root: Path, snapshot: RegistryProvenance, sources: Sequence[CommittedDelivery], observations: Mapping[str, RecipientActivity], *, assignment_read: NotificationAssignmentRead, owner_lookup: str | None=None) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
    """Original assignment and read authorities own both display projections."""
    from .notification_assignment import NotificationAssignment
    if len(sources) > cls.window_limit:
        raise ValueError('Notification reads require a bounded visible message window')
    keys = {(source.message.seq, source.message.message_id) for source in sources}
    result: dict[tuple[int, str], list[MessageNotification]] = {key: [] for key in keys}
    if not keys:
        return {}
    rows = assignment_read.resolve(root)
    reads = ReadLedger(root / ReadLedger.filename)
    document = reads.read()
    for source, outcomes in NotificationAssignment.for_deliveries(sources, rows):
        key = (source.message.seq, source.message.message_id)
        for outcome in outcomes:
            if not cls.includes_recipient(source, outcome.recipient, owner_lookup):
                continue
            observation = observations[outcome.recipient.recipient_lookup]
            notification = observation.after_inbox_read(outcome.project(observation), source, reads, document, snapshot)
            displayed_to = observation.displayed_recipient(notification, source, reads, document, snapshot)
            result[key].append(replace(notification, displayed_to=displayed_to, changed=notification.changed or bool(displayed_to)))
        direct_read = cls.direct_read_notification(source, snapshot, reads, document, owner_lookup=owner_lookup)
        if direct_read is not None:
            result[key].append(direct_read)
    return {key: tuple(rows) for key, rows in result.items()}

@classmethod
def for_sources(cls, root: Path, registry: Registration, owner: Thread, sources: Sequence[CommittedDelivery], *, assignment_read: NotificationAssignmentRead) -> tuple[MessageNotification, ...]:
    """Project outcomes from the caller's original certified source window."""
    projected = cls.delivery_window(root, registry, sources, owner_lookup=owner.incarnation.lookup, assignment_read=assignment_read)
    return tuple((replace(notification, message=source.message) for source in sources for notification in projected[source.message.seq, source.message.message_id]))

@dataclass(frozen=True)
class DeliverySources(WireSourcePointer['CommittedDelivery'], CheckpointTable, TypedTable):
    seq: int = field(metadata={'sql': Column(primary_key=True, check='seq>0')})
    message_id: str
    sender_lookup: str
    indexes = (Index(('sender_lookup', 'seq')),)

    def delivery(self, stream, root_id: str) -> CommittedDelivery:
        """A pointer has no message authority: resolve its original frozen row."""
        return self.decode_bytes(self.read_bytes(stream), root_id)

    def decode_bytes(self, raw: bytes, root_id: str) -> CommittedDelivery:
        """One frozen seq/id/audience relation for locked and snapshot readers."""
        from .bus_publication import CommittedDelivery, unique_wire_object
        try:
            record = json.loads(raw, object_pairs_hook=unique_wire_object)
            if not isinstance(record, Mapping):
                raise ValueError('Certified initial JSON must be an object.')
            original = CommittedDelivery.from_wire(record, root_id)
        except RelationViolationError:
            raise
        except (ValueError, TypeError) as error:
            raise RelationViolationError('Certified initial row is invalid.') from error
        if original.message.reference != self.reference or original.audience.sender_lookup != self.sender_lookup:
            raise RelationViolationError('Certified source differs from its frozen wire row.')
        return original

    @property
    def reference(self):
        from .message_reference import MessageReference
        return MessageReference(self.seq, self.message_id)

def references(self, references) -> Iterator[CommittedDelivery]:
    """Capture exact seq/id originals through the existing sealed pointers."""
    marks = ','.join(('?' for _ in references))
    self.require_current()
    rows = DeliverySources.select(self.connection, where=f'seq IN ({marks})', parameters=tuple((ref.seq for ref in references)))
    by_sequence = {row.seq: row for row in rows}
    ordered = []
    for reference in references:
        row = by_sequence.get(reference.seq)
        if row is None or row.reference != reference:
            raise RelationViolationError('Notification reference is not its original source')
        ordered.append(row)
    return self.capture_sources(tuple(ordered))

