@dataclass(frozen=True, slots=True)
class ProvenSourceCoverage:
    """One bounded source read and its corroborated original native inputs.

    This detached result lives only for the caller's read/publication operation.
    SQL identity, wire witness and live owner checks remain with the cursor;
    these historical observations never grant admission or replay.
    """
    wire_root_id: str
    recipient_lookup: str
    covered_seq: int
    inputs: tuple[HistoricalNativeInput, ...]
    no_wake_seqs: tuple[int, ...]
    blocked_seq: int | None
    more_sources: bool = False
    source_witness: PrefixWitness = field(kw_only=True)

    @property
    def injected_source_seqs(self) -> tuple[int, ...]:
        return tuple(dict.fromkeys((item.source_seq for item in self.inputs)))

    def evidence(self, *, through_seq: int | None=None) -> tuple[HistoricalNativeInput, ...]:
        """Consume the native inputs already corroborated in this source read."""
        if through_seq is None:
            return self.inputs
        return tuple((item for item in self.inputs if item.source_seq <= through_seq))

    def last_proof(self, source_seq: int) -> HistoricalNativeInput | None:
        if source_seq == 0:
            return None
        matching = [item for item in self.inputs if item.source_seq == source_seq and item.expected_prompt_equality_established]
        if not matching:
            raise IdentityConflict('current cursor source lacks live-bound native proof')
        return matching[-1]

def _page(self, request: CoveragePage) -> tuple[PrefixWitness, tuple[CommittedDelivery, ...], bool]:
    deadline = time.monotonic() + _MAX_SCAN_SECONDS
    remaining_before = self.contention.remaining if self.contention is not None else 0.0
    with self.bus.log.certified_read(blocking=False, contention=self.contention) as source:
        waited = remaining_before - self.contention.remaining if self.contention is not None else 0.0
        if time.monotonic() > deadline + waited:
            raise IdentityConflict('source coverage exceeded its scan deadline')
        if source.marker.root_id != self.wire_root_id:
            raise IdentityConflict('source coverage private wire root changed')
        witness, initials, more = source.addressed_page(self.bus.log, request)
        if request.after_seq > max(witness.latest_source_seq, source.marker.admission_after_seq):
            raise IdentityConflict('source coverage prefix exceeds certified initials')
        request.require_exhausted(more)
    return (witness, tuple(initials), more)

def _selected_inputs(self, seq: int, recipient: FrozenRecipient, lifecycle: AssignmentState, receipt: AcceptedCohort, source_reads: NativeEvidenceScope) -> tuple[HistoricalNativeInput, ...]:
    assignments = [a for a in receipt.assignments if a.recipient_lookup == self.recipient_lookup and a.recipient == recipient.canonical_thread]
    if len(assignments) != 1 or assignments[0].lifecycle.mode != lifecycle.mode:
        raise IdentityConflict('selected claim differs from frozen bus recipient')
    if not lifecycle.mode.active:
        return ()
    evidence = self.native_inputs(seq, source_reads=source_reads)
    if lifecycle.mode.proves_source(evidence) and all((p.assignment_id == assignments[0].assignment_id for p in evidence)):
        return evidence
    return ()

def prefix(self, *, through_seq: int | None=None, source_reads: NativeEvidenceScope | None=None) -> ProvenSourceCoverage:
    """Rescan the whole activation prefix; no persisted high-water is trusted."""
    from .native_entries import NativeEvidenceScope
    with NativeEvidenceScope.borrow(source_reads) as source_reads:
        with self.bus.log.certified_read(blocking=False, contention=self.contention) as source:
            marker = source.marker
            if marker.root_id != self.wire_root_id:
                raise IdentityConflict('current source admission root changed')
            floor = marker.admission_after_seq
        if through_seq is not None and 0 < through_seq <= floor:
            raise IdentityConflict('current source proof precedes this activation')
        covered, inputs, no_wake, witness = (floor, [], [], None)
        for _ in range(self.page_budget):
            page = self.read(after_seq=covered, partial=True, source_reads=source_reads)
            if page.covered_seq < covered:
                raise IdentityConflict('canonical source coverage regressed between pages')
            if witness is not None and page.source_witness != witness:
                raise IdentityConflict('certified source changed between coverage pages')
            witness, covered = (page.source_witness, page.covered_seq)
            inputs.extend(page.inputs)
            no_wake.extend(page.no_wake_seqs)
            if through_seq is not None and covered >= through_seq or page.blocked_seq is not None or (not page.more_sources):
                return ProvenSourceCoverage(self.wire_root_id, self.recipient_lookup, covered if covered > floor else 0, tuple(inputs), tuple(no_wake), page.blocked_seq, page.more_sources, source_witness=witness)
        raise IdentityConflict('source coverage exceeded bounded canonical page budget')

class Publisher:

    def __init__(self, log: WireLog, registry: Registration, channels: ChannelCatalog, *, private_response_writes: bool=False, private_initial_writes: bool=False, private_claim_writes: bool=False):
        self.log = log
        self._registry = registry
        self._channels = channels
        self._private_response_writes = private_response_writes
        self._private_initial_writes = private_initial_writes
        self._private_claim_writes = private_claim_writes

    def _validate_publish_request(self, message: Message, *, registry_snapshot: RegistrySnapshot | None=None, catalog: CatalogDocument | None=None) -> tuple[str, str]:
        """Resolve the public route from the acquired declarations when supplied."""

        def canonical(name: str) -> str:
            if registry_snapshot is None:
                return self._registry.canonical_name(name)
            return registry_snapshot.canonical_name(name)

        def exists(name: str) -> bool:
            if registry_snapshot is None:
                return name in self._registry
            return canonical(name) in registry_snapshot.threads
        if not exists(message.sender):
            raise UnregisteredThreadError(f'Sender {message.sender!r} is not a registered thread.')
        if BuiltinChannel.aggregate_target(message.target) or (is_channel_target(message.target) and (catalog if catalog is not None else self._channels.read()).is_view_target(message.target)):
            raise RelationViolationError(f'View {message.target!r} is a projection, not a routable target.')
        if not is_channel_target(message.target) and (not exists(message.target)):
            raise UnregisteredThreadError(f'Target {message.target!r} is not a registered thread.')
        sender = canonical(message.sender)
        target = message.target
        if not is_channel_target(target) and canonical(target) == sender:
            raise RelationViolationError(f'Thread {sender!r} cannot message itself.')
        return (sender, target)

    def _prepare_message_unlocked(self, message: Message, *, sender: str, target: str, sequence: int, snapshot: RegistrySnapshot | None=None, original_source: CertifiedSourceRead | None=None) -> Message:
        snapshot = snapshot or self._registry.snapshot()
        if original_source is not None:
            original_source.require_marker(self.log._private_marker_unlocked())
        message.require_task_publication(sender, snapshot, original_source)

        def resolve_mention(name: str) -> str | None:
            canonical = snapshot.canonical_name(name)
            thread = snapshot.threads.get(canonical)
            if thread is not None and thread.role.executable and snapshot.statuses[canonical].visible:
                return canonical
            return None
        return replace(message, sender=sender, target=target, seq=sequence, sender_role=snapshot.threads[sender].role, mentions=ThreadMention.find(message.body, resolve_mention))

    def publish_ordinary(self, message: Message, *, _human_origin: HumanOrigin | None=None) -> Message:
        """Publish through the canonical audience/decision writer.

        A truly fresh root is initialized once under the bus lock. Existing
        unmarked data requires the explicit archival cutover; a send never
        rewrites history or falls back to an uncoordinated append.
        """
        from .active_route import guard_original_root_write
        if _human_origin is not None and type(_human_origin) is not HumanOrigin:
            raise RelationViolationError('Human origin must be a typed local USER identity.')
        with guard_original_root_write(self.log.path.parent), self.log.locked() as bus_lock:
            if not self.log.read_metadata_unlocked().private:
                self._validate_publish_request(message)
                self._initialize_private_protocol_unlocked()
            return self.publish_initial_cohort(message, _bus_lock=bus_lock, _human_origin=_human_orig

def _publish_keyed_response_unlocked(self, intent: PublicationIntents, *, conversation, registry_snapshot: RegistrySnapshot | None=None) -> Message:
    """Internal append with bus lock; a supplied registry snapshot stays locked."""
    from .audience_manifest import MAX_WIRE_SEQ
    if self._private_response_writes is not True:
        raise RelationViolationError('Private response publication is disabled.')
    matched, previous_sequence, metadata = self.log._keyed_receipt_unlocked(intent)
    if matched is not None:
        return matched
    message = intent.message
    sender, target = self._validate_publish_request(message, registry_snapshot=registry_snapshot)
    if registry_snapshot is None:
        executable = self._registry.require(sender).role.executable
    else:
        executable = registry_snapshot.threads[sender].role.executable
    if not executable:
        raise RelationViolationError('Keyed response sender must be executable.')
    if intent.publication_key != canonical_publication_key(intent.execution_id, target):
        raise RelationViolationError('Response publication key does not match its route.')
    last_sequence = max(metadata.last_seq, previous_sequence)
    if last_sequence >= MAX_WIRE_SEQ:
        raise RelationViolationError('Private bus sequence is exhausted.')
    stored = self._prepare_message_unlocked(message, sender=sender, target=target, sequence=last_sequence + 1, snapshot=registry_snapshot)
    if not intent.matches_publication(stored):
        raise RelationViolationError('Stored response does not match publication intent.')
    row = conversation.record(metadata.root_id, stored, intent)
    CommittedDelivery.from_wire(row, metadata.root_id)
    self.log._append_private_unlocked(metadata, row)
    return stored

class ReadLedger(Sealed, ThreadOwnedState, LockedStore[ReadDocument]):
    filename = 'read_ledger.json'

    @property
