def displayed_recipient(self, original: CommittedDelivery, recipient, snapshot: RegistrySnapshot, *, document=None):
    """Return recorded human display evidence for this exact frozen recipient.

        Processing, assignment acceptance and a reply cannot grant this fact.
        A reused name with a different creation identity cannot inherit it.
        """
    return snapshot.recipient(recipient, original).read_effect(self, original.message, snapshot, document=document)

@dataclass(frozen=True, slots=True)
class RegistrySnapshot(RegistryPresence, RegistryProvenance):
    threads: Mapping[str, Thread]
    statuses: Mapping[str, ThreadStatus]
    last_seen: Mapping[str, float]
    aliases: Mapping[str, str]
    owner_generations: Mapping[str, int]
    admission_generations: Mapping[str, int]
    by_lookup: Mapping[str, Thread] = field(repr=False, compare=False)

    def __post_init__(self) -> None:
        super(RegistrySnapshot, self).__post_init__()
        seen: set[str] = set()
        for thread in self.threads.values():
            lookup = thread.incarnation.require_recorded().lookup
            if lookup in seen:
                raise RelationViolationError('Registry creation identities collide.')
            seen.add(lookup)
            if self.by_lookup.get(lookup) is not thread:
                raise RelationViolationError('Snapshot lookup index differs from its threads.')
        if len(seen) != len(self.by_lookup):
            raise RelationViolationError('Snapshot lookup index includes an unregistered thread.')

    @classmethod
    def capture(cls, document: RegistryDocument) -> RegistrySnapshot:
        """One live registry cut owns the index and all its source maps."""
        indexed: dict[str, Thread] = {}
        for thread in document.threads.values():
            incarnation = thread.incarnation.require_recorded()
            lookup = incarnation.lookup
            indexed[lookup] = thread
        return cls(threads=MappingProxyType(dict(document.threads)), statuses=MappingProxyType(dict(document.statuses)), last_seen=MappingProxyType(dict(document.last_seen)), aliases=MappingProxyType(dict(document.aliases)), owner_generations=MappingProxyType(dict(document.owners.generations)), admission_generations=MappingProxyType(dict(document.admissions.generations)), by_lookup=MappingProxyType(indexed))

    def displayed_recipient_effect(self, reads, message, thread: Thread, *, document=None):
        if not reads.human(thread.role):
            return ()
        return super().displayed_recipient_effect(reads, message, thread, document=document)

    def recipient(self, recipient: FrozenRecipient, original: CommittedDelivery) -> RegisteredRecipient | RetiredRecipient:
        """A missing live thread was retired only if the original send names it."""
        lookup = recipient.recipient_lookup
        thread = self.by_lookup.get(lookup)
        if thread is not None:
            if thread.name != self.canonical_name(recipient.canonical_thread):
                raise RelationViolationError('Frozen recipient name does not match its lookup.')
            return RegisteredRecipient(thread)
        if recipient not in original.audience.recipients:
            raise UnregisteredThreadError('Recipient lookup is not in the original message.')
        return RetiredRecipient(lookup)

    def retired(self, name: str) -> bool:
        """Removal keeps the name's generations; they are the deletion record."""
        return name not in self.threads and name in self.admission_generations

    def restorable_aliases(self, available: Mapping[str, Thread], retained: Mapping[str, str]) -> dict[str, str]:
        matching = {name for name in self.threads.keys() & available.keys() if self.threads[name].incarnation == available[name].incarnation}
        unoccupied = self.aliases.keys() - available.keys() - retained.keys()
        return {alias: self.aliases[alias] for alias in unoccupied if self.aliases[alias] in matching}

    def owner_identity(self, name: str) -> OwnerIdentity:
        canonical = self.canonical_name(name)
        return OwnerIdentity(self.threads[canonical].incarnation, self.owner_generations[canonical])

    def admission_identity(self, name: str) -> AdmissionIdentity:
        canonical = self.canonical_name(name)
        return AdmissionIdentity(self.threads[canonical].incarnation, self.admission_generations[canonical])

    def owner_binding(self, name: str) -> ThreadOwnerBindi

def recipient(self, recipient: FrozenRecipient, original: CommittedDelivery) -> RegisteredRecipient | RetiredRecipient:
    """A missing live thread was retired only if the original send names it."""
    lookup = recipient.recipient_lookup
    thread = self.by_lookup.get(lookup)
    if thread is not None:
        if thread.name != self.canonical_name(recipient.canonical_thread):
            raise RelationViolationError('Frozen recipient name does not match its lookup.')
        return RegisteredRecipient(thread)
    if recipient not in original.audience.recipients:
        raise UnregisteredThreadError('Recipient lookup is not in the original message.')
    return RetiredRecipient(lookup)

@dataclass(frozen=True)
class ResponseConversation:
    responder: FrozenRecipient
    obligation: ResponseObligation
    sources: tuple[CommittedDelivery, ...]

    @classmethod
    def source_references(cls, snapshot, obligation: ResponseObligation) -> tuple[MessageReference, ...]:
        """The selected original messages belonging to this exact reply route."""
        if obligation.execution_id != snapshot.execution.execution_id:
            raise IdentityConflict('Response obligation belongs to another execution')
        originals = tuple((assignment.source for assignment in snapshot.assignments if assignment.lifecycle.exact_target == obligation.exact_target))
        if not originals:
            raise IdentityConflict('Response obligation has no original conversation')
        return originals

    @classmethod
    def answer_references(cls, snapshot, obligation: ResponseObligation, following: tuple[MessageReference, ...]) -> tuple[MessageReference, ...]:
        return tuple(dict.fromkeys((*cls.source_references(snapshot, obligation), *following)))

    @classmethod
    def capture(cls, bus, snapshot, obligation: ResponseObligation):
        originals = cls.source_references(snapshot, obligation)
        marker = bus.log._private_marker_unlocked()
        sources = bus.log.delivery_cohorts_unlocked(marker.root_id, tuple((reference.seq for reference in originals)))
        if len(sources) != len(originals):
            raise IdentityConflict('Response obligation has no complete original conversation')
        if {source.message.reference for source in sources} != set(originals):
            raise IdentityConflict('Response conversation lost an original source')
        if any((source.message.exact_reply_target != obligation.exact_target for source in sources)):
            raise IdentityConflict('Response obligation differs from its original routes')
        return cls(FrozenRecipient(snapshot.execution.owner_lookup, snapshot.execution.owner_thread), obligation, sources)

    def audience(self, message: Message):
        if message.sender != self.responder.canonical_thread:
            raise IdentityConflict('Response conversation sender changed')
        if message.target != self.obligation.exact_target:
            raise IdentityConflict('Response conversation route changed')
        members = {}
        for source in self.sources:
            if source.message.exact_reply_target != self.obligation.exact_target:
                raise IdentityConflict('Response conversation differs from original route')
            audience = source.audience
            participants = list(audience.recipients)
            if source.message.sender_role.executable:
                participants.append(FrozenRecipient(audience.sender_lookup, audience.sender_name))
            if self.responder not in audience.recipients:
                raise IdentityConflict('Responder was not in original frozen audience')
            for member in participants:
                previous = members.setdefault(member.recipient_lookup, member)
                if previous != member:
                    raise IdentityConflict('Conversation participant identity changed')
        members.pop(self.responder.recipient_lookup, None)
        recipients = tuple(members.values())
        if not is_channel_target(self.obligation.exact_target):
            recipients = tuple((m for m in recipients if m.canonical_thread == self.obligation.exact_target))
        revision = hashlib.sha256('\n'.join((source.audience.digest for source in self.sources)).encode()).hexdigest()
        return freeze_audience(message, recipients, revision, sender_lookup=self.responder.recipient_lookup, sender_name=self.responder.canonical_thread)

    def record(self, root_id, message, intent):
        from .bus_publication import PRIVATE_WIRE_FIELD, initial_sideband, public_envelope_digest
        from .delivery_policy import KeyedResponseReceipt, ResponseDeliveryPolicy
        from .field_codec

@staticmethod
def capture_sent_outcomes(comms: Comms, owner: Thread, sources: Sequence[CommittedDelivery], assignment_read: NotificationAssignmentRead) -> tuple[SentMessageOutcome, ...]:
    """Project optional prompt context from the drain's captured source and SQL cuts."""
