@dataclass(frozen=True, slots=True)
class WakeDecision:
    recipient: str
    audience: MessageAudience
    wake_mode: WakePolicy

    def __post_init__(self) -> None:
        if not isinstance(self.recipient, str) or not self.recipient:
            raise ValueError('decision recipient requires a stable lookup.')
        if type(self.audience) is not MessageAudience:
            raise TypeError('wake decision requires MessageAudience.')
        if self.audience.observer and self.wake_mode.active:
            raise ValueError('observer decisions must be passive')

    def to_wire(self) -> dict[str, str]:
        if self.audience.observer:
            return {'recipient_lookup': self.recipient, 'no_wake': 'unmentioned_observer'}
        return {'recipient_lookup': self.recipient, 'audience': self.audience.value, 'wake_mode': self.wake_mode.declared_name}

    def initial_notification(self, recipient, *, observation):
        return self.wake_mode.initial_state().notification(recipient, observation=observation)

def _member_decision(message: Message, recipient: FrozenRecipient, control: ControlClassification, channel: bool, effective_mentions: frozenset[str]) -> WakeDecision:
    if not channel:
        audience = MessageAudience.DIRECT
    elif effective_mentions:
        audience = MessageAudience.MENTIONED
    else:
        audience = MessageAudience.COLLECTIVE
    if message.notice or message.membership is not None or control.passive:
        mode = PassiveWake()
    elif not channel:
        mode = FullWake()
    elif effective_mentions:
        if recipient.canonical_thread not in effective_mentions:
            return WakeDecision(recipient.recipient_lookup, MessageAudience.OBSERVER, PassiveWake())
        mode = FullWake()
    else:
        mode = BoundedTriageWake()
    return WakeDecision(recipient.recipient_lookup, audience, mode)

def resolve_wake(message: Message, *, recipient: FrozenRecipient, frozen_audience: FrozenAudience, control: ControlClassification) -> WakeDecision | None:
    """Resolve one member; prefer resolve_wake_cohort for the full frozen N.

    ``None`` means the lookup/name pair is absent; OBSERVER is a frozen
    unmentioned observer, never a claim. Neither pure API proves bus commit.
    """
    if type(recipient) is not FrozenRecipient:
        raise TypeError('wake requires a FrozenAudience and FrozenRecipient.')
    channel, effective_mentions = _validated_context(message, frozen_audience, control)
    if recipient not in frozen_audience.recipients:
        return None
    return _member_decision(message, recipient, control, channel, effective_mentions)

